        onChange={event => this.props.onChangeSelectWeekDays(item.name, event.target.checked)}\r\n                                            />\r\n                                            <label htmlFor={`ckb-${item.name}`} />\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            );\r\n                        })\r\n                    }\r\n                    {\r\n                        isHost && enableSyncWorkingShift &&\r\n                        <div className=\"table-cell cell-syncdata\">\r\n                            <span className=\"fa fa-refresh\" title=\"Sync data from OWP\"\r\n                                onClick={this.props.onSyncData}\r\n                            />\r\n                        </div>\r\n                    }\r\n                    <div className=\"table-cell cell-modifier\">Modified by</div>\r\n                </div>\r\n            </Fragment>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { Droppable, Draggable } from 'react-beautiful-dnd';\r\n\r\nimport RowTeam from './RowTeam';\r\n\r\nexport default class DroppableTeam extends PureComponent {\r\n    render() {\r\n        const { isHost, shiftOptions, data } = this.props;\r\n        return (\r\n            <Droppable droppableId=\"droppable\" isDropDisabled={!isHost} type=\"droppableTeam\">\r\n                {\r\n                    provided =>\r\n                        <div ref={provided.innerRef} {...provided.droppableProps}>\r\n                            {\r\n                                data.map((team, gindex) =>\r\n                                    <Draggable key={team.teamId} draggableId={team.teamId}\r\n                                        index={gindex} isDragDisabled={!isHost}\r\n                                    >\r\n                                        {\r\n                                         