ass Search extends Component {\r\n    handleTeamChange = selectedItems => {\r\n        const ids = selectedItems.map(item => item.id);\r\n        this.props.onChange('teamIds', ids.join(','));\r\n    };\r\n\r\n    handleEmployeeChange = value => {\r\n        this.props.onChange('employee', value);\r\n    };\r\n\r\n    handleDateChange = (fromDate, toDate) => {\r\n        this.props.onChange('fromDate', fromDate);\r\n        this.props.onChange('toDate', toDate);\r\n    };\r\n\r\n    handleCategoryChange = e => {\r\n        this.props.onChange('isLocal', e.target.value);\r\n    };\r\n\r\n    handleSubmit = event => {\r\n        this.props.onSubmit(event.target.name === 'currentWeek');\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <div className=\"filter\">\r\n                <div className=\"form-horizontal clearfix\">\r\n                    <div className=\"form-group form-group--l\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Week</label>\r\n                        </div>\r\n                        <div className=\"calendar-form\">\r\n                            <WeekPicker\r\n                                fromDate={this.props.filter.fromDate}\r\n                                toDate={this.props.filter.toDate}\r\n                                onChange={this.handleDateChange}\r\n                            />\r\n                        </div>\r\n                    </div>\r\n                    <div className=\"form-group form-group--m\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Sec./Team</label>\r\n                        </div>\r\n                        <div className=\"select-form\">\r\n                            <TreeMultiselect\r\n                                data={this.props.teamOptions}\r\n                                isSelectedAll\r\n                                onChange={this.handleTeamChange}\r\n                            />\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div className=\"form-group form-group--m\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Category</label>\r\n                        </div>\r\n                        <div className=\"select-form\">\r\n                            <select className=\"form-control\" value={this.props.filter.isLocal} onChange={this.handleCategoryChange}>\r\n                                <option value >All</option>\r\n                                <option value=\"0\">Expat</option>\r\n                                <option value=\"1\">Local</option>\r\n                            </select>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div className=\"form-group form-group--m\">\r\n                        <div className=\"label-form\">\r\n                            <label className=\"control-label\">Employee</label>\r\n                        </div>\r\n                        <div className=\"select-form\">\r\n                            <Autocomplete\r\n                                className=\"form-control\"\r\n                                sources={this.props.employeeOptions}\r\n                                onInput={this.props.onSearchEmployees}\r\n                                onChange={this.handleEmployeeChange}\r\n                            />\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div className=\"form-horizontal clearfix\">\r\n                    <div className=\"button-group\">\r\n                        <button className=\"btn btn-primary\" onClick={this.handleSubmit}>Submit</button>\r\n                        <button className=\"btn btn-primary\" name=\"currentWeek\" onClick={this.handleSubmit}>\r\n                            Current Week\r\n                        </button>\r\n                        {\r\n                            this.props.showExportExcel &&\r\n                            <Dropdown id={`dropdownExportExcel`} componentClass=\"div\">\r\n                                <Dropdown.Toggle useAnchor className=\"btn btn-excel\">\r\n                                    Excel\r\n                                </Dropdown.Toggle>\r\n                                <Dropdown.Menu>\r\n                                    <MenuItem onClick={this.props.onExportExcel}>Upload</MenuItem>\r\n                                    <MenuItem onClick={this.props.onExportExcelDriverPickup}>Driver Pickup</MenuItem>\r\n                                </Dropdown.Menu>\r\n                            </Dropdown>\r\n                        }\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport PropTypes from 'prop-types';\r\n\r\nexport default class Autocomplete extends Component {\r\n    static propTypes = {\r\n        sources: PropTypes.arrayOf(PropTypes.object),\r\n        className: PropTypes.string,\r\n        isDisabled: PropTypes.bool,\r\n        onInput: PropTypes.func,\r\n        onChange: PropTypes.func\r\n    };\r\n\r\n    static defaultProps = {\r\n        sources: [],\r\n        className: '',\r\n        isDisabled: false,\r\n        onInput: function () {\r\n            // This is intentional\r\n        },\r\n        onChange: function () {\r\n            // This is intentional\r\n        }\r\n    };\r\n\r\n    componentDidMount() {\r\n        this.$el = $(this.el);\r\n        this.updateAutocomplete();\r\n    }\r\n\r\n    shouldComponentUpdate(nextProps) {\r\n        return this.props.sources !== nextProps.sources\r\n            || this.props.className !== nextProps.className\r\n            || this.props.isDisabled !== nextProps.isDisabled;\r\n    }\r\n\r\n    componentDidUpdate() {\r\n        this.updateAutocomplete();\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        this.$el.autocomplete('destroy');\r\n    }\r\n\r\n    updateAutocomplete = () => {\r\n        const sources = this.props.sources;\r\n        this.$el.autocomplete({\r\n            source: sources,\r\n            minLength: 2,\r\n            select: (event, ui) => this.handleChange(event, ui),\r\n            change: (event, ui) => this.handleChange(event, ui)\r\n        });\r\n    };\r\n\r\n    handleInput = event => {\r\n        this.props.onInput(event.target.value);\r\n    };\r\n\r\n    handleChange = (event, ui) => {\r\n        let value = 0,\r\n            label = '';\r\n        if (ui && ui.item) {\r\n            label = ui.item.value;\r\n            value = ui.item.id;\r\n        } else {\r\n            if (this.$el.value === '') {\r\n                value = '';\r\n            }\r\n        }\r\n\r\n        this.props.onChange({ value, label });\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <input\r\n                ref={el => this.el = el}\r\n                type=\"text\"\r\n                className={this.props.className}\r\n                disabled={this.props.isDisabled}\r\n                onInput={this.handleInput}\r\n            />\r\n        );\r\n    }\r\n}","import React from 'react';\r\nimport PropTypes from 'prop-types';\r\n\r\nimport buildData from './buildData';\r\nimport TreeNode from './TreeNode';\r\n\r\nconst updateParent = (floatData, parentKey, isChecked) => {\r\n    const index = floatData.findIndex(item => item.key === parentKey),\r\n        siblings = floatData.filter(item => item.parentKey === parentKey),\r\n        selected = siblings.filter(item => item.checked);\r\n    floatData[index] = { ...floatData[index], checked: siblings.length === selected.length };\r\n\r\n    if (floatData[index].parentKey !== null && floatData[index].parentKey !== '') {\r\n        updateParent(floatData, floatData[index].parentKey, isChecked);\r\n    }\r\n};\r\n\r\nconst updateChild = (floatData, itemkey, isChecked) => {\r\n    const totalItems = floatData.length;\r\n    for (let i = 0; i < totalItems; i++) {\r\n        if (floatData[i].parentKey === itemkey) {\r\n            floatData[i] = { ...floatData[i], checked: isChecked };\r\n            updateChild(floatData, floatData[i].key, isChecked);\r\n        }\r\n    }\r\n};\r\n\r\nconst getSelectedText = (floatData) => {\r\n    const items = floatData.filter(item => item.isLeaf),\r\n        selected = items.filter(item => item.checked);\r\n    let text = '';\r\n\r\n    if (selected.length === 0) {\r\n        text = 'Select options';\r\n    } else if (items.length === selected.length) {\r\n        text = 'All selected';\r\n    } else {\r\n        text = `${selected.length} selected`;\r\n    }\r\n\r\n    return text;\r\n};\r\n\r\nconst getSelectedItems = (floatData) => {\r\n    return floatData.filter(item => item.isLeaf && item.checked);\r\n};\r\n\r\nlet id = 1;\r\n\r\nexport default class TreeMultiselect extends React.Component {\r\n    static propTypes = {\r\n        data: PropTypes.arrayOf(PropTypes.object).isRequired,\r\n        isSelectedAll: PropTypes.bool,\r\n        onChange: PropTypes.func\r\n    }\r\n\r\n    static defaultProps = {\r\n        data: [],\r\n        isSelectedAll: false,\r\n        onChange: function () { }\r\n    }\r\n\r\n    static getDerivedStateFromProps(props, state) {\r\n        if (state.original === props.data) {\r\n            return null;\r\n        }\r\n\r\n        return { ...buildData(props.data || [], props.isSelectedAll), original: props.data };\r\n    }\r\n\r\n    constructor(props) {\r\n        super(props);\r\n        this.id = `multiselect-treeview-${props.id || id++}`;\r\n        this.state = {\r\n            selectedText: 'Select options',\r\n            opened: false\r\n        };\r\n    }\r\n\r\n    componentDidMount() {\r\n        document.addEventListener('click', this.handleDocumentClick);\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        document.removeEventListener('click', this.handleDocumentClick);\r\n    }\r\n\r\n    handleDocumentClick = (event) => {\r\n        const clickOutside = this.wrapper && !this.wrapper.contains(event.target);\r\n        if (clickOutside && this.state.opened) {\r\n            this.setState({ opened: false });\r\n        }\r\n    }\r\n\r\n    onToggle = () => {\r\n        this.setState((prevState) => { return { opened: !prevState.opened }; });\r\n    }\r\n\r\n    handleSelectAll = event => {\r\n        let floatData = [...this.state.floatData];\r\n        const totalItems = floatData.length;\r\n        for (let i = 0; i < totalItems; i++) {\r\n            floatData[i] = { ...floatData[i], checked: event.target.checked };\r\n        }\r\n\r\n        this.props.onChange && this.props.onChange(getSelectedItems(floatData));\r\n        this.setState({ floatData });\r\n    }\r\n\r\n    handleSelect = (itemkey, isChecked) => {\r\n        let floatData = [...this.state.floatData];\r\n        const index = floatData.findIndex(item => item.key === itemkey);\r\n        floatData[index] = { ...floatData[index], checked: isChecked };\r\n\r\n        updateChild(floatData, itemkey, isChecked);\r\n        if (floatData[index].parentKey !== null && floatData[index].parentKey !== '') {\r\n            updateParent(floatData, floatData[index].parentKey, isChecked);\r\n        }\r\n\r\n        this.props.onChange && this.props.onChange(getSelectedItems(floatData));\r\n        this.setState({ floatData });\r\n    }\r\n\r\n    render() {\r\n        const { floatData, data } = this.state;\r\n        const selected = floatData.filter(item => item.checked);\r\n        const selectedText = getSelectedText(floatData);\r\n\r\n        return (\r\n            <div id={this.id} className=\"multiselect-treeview\" ref={element => this.wrapper = element}>\r\n                <div className=\"multiselect-treeview-dropdown-button\" onClick={this.onToggle}>\r\n                    <span className=\"selected-text\">{selectedText}</span>\r\n                    <span className=\"up-down-icon\"><span className={this.state.opened ? 'up' : 'down'} /></span>\r\n                </div>\r\n                <div className={`multiselect-treeview-dropdown-list ${this.state.opened ? '' : 'hidden'}`}>\r\n                    <div className=\"multiselect-treeview-select-all\">\r\n                        <div className=\"checkbox-wrapper\">\r\n                            <input type=\"checkbox\" id=\"selectAll\"\r\n                                checked={floatData.length === selected.length}\r\n                                onChange={this.handleSelectAll}\r\n                            />\r\n                            <label htmlFor=\"selectAll\"> Select all</label>\r\n                        </div>\r\n                    </div>\r\n                    <div className=\"multiselect-treeview-items\">\r\n                        {\r\n                            data.map(item =>\r\n                                <ul key={item.key}>\r\n                                    <li className=\"multiselect-treeview-item\">\r\n                                        <TreeNode\r\n                                            data={item}\r\n                                            floatData={floatData}\r\n                                            onSelect={this.handleSelect}\r\n                                        />\r\n                                    </li>\r\n                                </ul>\r\n                            )\r\n                        }\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent, Fragment } from 'react';\r\n\r\nexport default class TreeNode extends PureComponent {\r\n    handleChange = event => {\r\n        const itemkey = this.props.data.key;\r\n        this.props.onSelect(itemkey, event.target.checked);\r\n    }\r\n\r\n    render() {\r\n        const { data, floatData } = this.props;\r\n        const itemIndex = floatData.findIndex(item => item.key === data.key);\r\n\r\n        return (\r\n            <Fragment>\r\n                <div className=\"checkbox-wrapper\">\r\n                    <input type=\"checkbox\" id={data.key} checked={floatData[itemIndex].checked} onChange={this.handleChange} />\r\n                    <label htmlFor={data.key}> {data.text}</label>\r\n                </div>\r\n                {\r\n                    data.items && data.items.length > 0 &&\r\n                    <ul>\r\n                        {\r\n                            data.items.map(item =>\r\n                                <li key={item.key} className=\"multiselect-treeview-item is-child\">\r\n                                    <TreeNode\r\n                                        data={item}\r\n                                        floatData={floatData}\r\n                                        onSelect={this.props.onSelect}\r\n                                    />\r\n                                </li>\r\n                            )\r\n                        }\r\n                    </ul>\r\n                }\r\n            </Fragment>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport moment from 'moment';\r\n\r\nimport { DateFormat } from '../constants';\r\n\r\nexport default class WeekPicker extends PureComponent {\r\n    componentDidMount() {\r\n        this.$el = $(this.el);\r\n        this.updateWeekPicker();\r\n\r\n        document.addEventListener('mousedown', this.handleClickOutside);\r\n    }\r\n\r\n    componentDidUpdate(prevProps) {\r\n        if (this.props.fromDate !== prevProps.fromDate || this.props.toDate !== prevProps.toDate) {\r\n            this.updateWeekPicker();\r\n        }\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        this.$el.weekpicker('destroy');\r\n        document.removeEventListener('mousedown', this.handleClickOutside);\r\n    }\r\n\r\n    handleClickOutside = event => {\r\n        if (this.wrapperRef && !this.wrapperRef.contains(event.target)) {\r\n            this.$el.hide();\r\n        }\r\n    };\r\n\r\n    updateWeekPicker = () => {\r\n        const vm = this;\r\n\r\n        this.$el.weekpicker({\r\n            firstDay: 1,\r\n            onSelect: function (dateText, startDateText, startDate, endDate) {\r\n                vm.props.onChange(moment(startDate).format(DateFormat), moment(endDate).format(DateFormat));\r\n                vm.$el.hide();\r\n            }\r\n        });\r\n\r\n        this.$el.weekpicker('setDate', new Date(new Date(this.props.fromDate)));\r\n    };\r\n\r\n    handleShowCalendar = () => {\r\n        this.$el.toggle();\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <div className=\"weekpicker-wrapper\" ref={node => this.wrapperRef = node}>\r\n                <input\r\n                    value={this.props.fromDate}\r\n                    onClick={this.handleShowCalendar}\r\n                    className=\"fromDate form-control\" readOnly\r\n                />\r\n                <input value={this.props.toDate}\r\n                    onClick={this.handleShowCalendar}\r\n                    className=\"toDate form-control\" readOnly\r\n                />\r\n                <div className=\"calendar\" ref={node => this.el = node} />\r\n                <i className=\"icon-calendar fa fa-calendar\" onClick={this.handleShowCalendar} />\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { Dropdown, MenuItem } from 'react-bootstrap';\r\n\r\nexport default class ColorDescription extends PureComponent {\r\n    render() {\r\n        return (\r\n            <Dropdown id={`dropdownColorDescription`} componentClass=\"span\" className=\"dropdown-color\">\r\n                <Dropdown.Toggle noCaret className=\"btn\">\r\n                    <img src=\"../wwwroot/sources/styl