teamId} draggableId={team.teamId}\r\n                                        index={gindex} isDragDisabled={!isHost}\r\n                                    >\r\n                                        {\r\n                                            (teamProvided, teamSnapshot) =>\r\n                                                <div>\r\n                                                    <RowTeam draggableProvided={teamProvided}\r\n                                                        isHost={isHost} data={team}\r\n                                                        shiftOptions={shiftOptions} isDragging={teamSnapshot.isDragging}\r\n                                                        showRemarkPopover={this.props.showRemarkPopover}\r\n                                                        onChangeSelectWeekDay={this.props.onChangeSelectWeekDay}\r\n                                                        onChangePublics={this.props.onChangePublics}\r\n                                                        onChangeTeamOrder={this.props.onChangeTeamOrder}\r\n                                                        onChangeShowRemarkPopover={this.props.onChangeShowRemarkPopover}\r\n                                                        onChangeShift={this.props.onChangeShift}\r\n                                                        onChangeDefaultShift={this.props.onChangeDefaultShift}\r\n                                                        onShowWeeklyDefaultShift={this.props.onShowWeeklyDefaultShift}\r\n                                                        onUpdateRemark={this.props.onUpdateRemark}\r\n                                                        onChangeOrder={this.props.onChangeOrder}\r\n                                                        onSelectEmployeeOfTeam={this.props.onSelectEmployeeOfTeam}\r\n                                                    />\r\n                                                    {teamProvided.placeholder}\r\n                                                </div>\r\n                                        }\r\n                                    </Draggable>\r\n                                )\r\n                            }\r\n                            {provided.placeholder}\r\n                        </div>\r\n                }\r\n            </Droppable>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport DroppableMember from './DroppableMember';\r\nimport DropdownOrder from '../../../shared/components/DropdownOrder';\r\n\r\nexport default class RowTeam extends PureComponent {\r\n    handleMoveUp = () => {\r\n        const { teamId } = this.props.data;\r\n        this.props.onChangeTeamOrder('up', teamId);\r\n    };\r\n\r\n    handleMoveDown = () => {\r\n        const { teamId } = this.props.data;\r\n        this.props.onChangeTeamOrder('down', teamId);\r\n    };\r\n\r\n    handleMoveTop = () => {\r\n        const { teamId } = this.props.data;\r\n        this.props.onChangeTeamOrder('top', teamId);\r\n    };\r\n\r\n    handleMoveBottom = () => {\r\n        const { teamId } = this.props.data;\r\n        this.props.onChangeTeamOrder('bottom', teamId);\r\n    };\r\n\r\n    handleChangePublic = event => {\r\n        const { teamId } = this.props.data;\r\n        this.props.onChangePublics(teamId, event.target.checked);\r\n    };\r\n\r\n    handleSelectEmployeeOfTeam = event => {\r\n        const { teamId } = this.props.data;\r\n        this.props.onSelectEmployeeOfTeam(teamId, null, event.target.checked);\r\n    };\r\n\r\n    render() {\r\n        const { isHost, draggableProvided, isDragging, shiftOptions } = this.props;\r\n        const { teamId, name, isPublic, isSelected, members } = this.props.data;\r\n        const enableSyncWorkingShift = document.getElementById('EnableSyncWorkingShift').checked;\r\n\r\n        return (\r\n            <div className={`${isDragging ? 'dragging' : ''}`}\r\n                ref={draggableProvided.innerRef} {...draggableProvided.draggableProps} {...draggableProvided.dragHandleProps}\r\n            >\r\n                <div className=\"row-team\">\r\n                    <div className=\"team-name\">\r\n                        <div>{name}</div>\r\n                        {\r\n                            isHost &&\r\n                            <DropdownOrder id={`dropdownTeam${teamId}`}\r\n                                onMoveUp={this.handleMoveUp}\r\n                                onMoveDown={this.handleMoveDown}\r\n                                onMoveTop={this.handleMoveTop}\r\n                                onMoveBottom={this.handleMoveBottom}\r\n                            />\r\n                        }\r\n                    </div>\r\n                    <div className=\"right-container\">\r\n                        {\r\n                            isHost && enableSyncWorkingShift &&\r\n                            <div className=\"cell-syncdata\">\r\n                                <div className=\"checkbox\">\r\n                                    <input type=\"checkbox\" className={`checkbox-custom`} id={`ckb-syncdata${teamId}`}\r\n                                        checked={isSelected} onChange={this.handleSelectEmployeeOfTeam}\r\n                                    />\r\n                                    <label htmlFor={`ckb-syncdata${teamId}`} />\r\n                                </div>\r\n                            </div>\r\n                        }\r\n                        <div className=\"cell-public\">\r\n                            <div className=\"checkbox\">\r\n                                <input type=\"checkbox\" className={`checkbox-custom`} id={`ckb-public${teamId}`}\r\n                                    checked={isPublic} disabled={!isHost} onChange={this.handleChangePublic}\r\n                                />\r\n                                <label htmlFor={`ckb-public${teamId}`}> Publish</label>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <DroppableMember isHost={isHost}\r\n                    teamId={teamId} data={members}\r\n                    shiftOptions={shiftOptions}\r\n                    showRemarkPopover={this.props.showRemarkPopover}\r\n                    onChangeSelectWeekDay={this.props.onChangeSelectWeekDay}\r\n                    onChangeShift={this.props.onChangeShift}\r\n                    onChangeDefaultShift={this.props.onChangeDefaultShift}\r\n                    onChangeShowRemarkPopover={this.props.onChangeShowRemarkPopover}\r\n                    onShowWeeklyDefaultShift={this.props.onShowWeeklyDefaultShift}\r\n                    onUpdateRemark={this.props.onUpdateRemark}\r\n                    onChangeOrder={this.props.onChangeOrder}\r\n                    onSelectEmployeeOfTeam={this.props.onSelectEmployeeOfTeam}\r\n                />\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { Droppable, Draggable } from 'react-beautiful-dnd';\r\n\r\nimport Row from './Row';\r\n\r\nexport default class DroppableMember extends PureComponent {\r\n    render() {\r\n        const { isHost, shiftOptions, teamId, data } = this.props;\r\n\r\n        return (\r\n            <Droppable droppableId={`dropable${teamId}`} isDropDisabled={!isHost} type={`droppableMember-${teamId}`}>\r\n                {\r\n                    provided =>\r\n                        <div ref={provided.innerRef} {...provided.droppableProps}>\r\n                            {\r\n                                data.map((member, eindex) =>\r\n                                    <Draggable key={`member${member.employeeId}`} draggableId={`member${member.employeeId}`}\r\n                                        index={eindex} isDragDisabled={!isHost}\r\n                                    >\r\n                                        {\r\n                                            (memberProvided, memberSnapshot) =>\r\n                                                <div>\r\n                                                    <Row draggableProvided={memberProvided}\r\n                                                        isHost={isHost} teamId={teamId} data={member}\r\n                                                        shiftOptions={shiftOptions} isDragging={memberSnapshot.isDragging}\r\n                                                        showRemarkPopover={this.props.showRemarkPopover}\r\n                                                        onChangeSelectWeekDay={this.props.onChangeSelectWeekDay}\r\n                                                        onChangeShift={this.props.onChangeShift}\r\n                                                        onChangeDefaultShift={this.props.onChangeDefaultShift}\r\n                                                        onChangeShowRemarkPopover={this.props.onChangeShowRemarkPopover}\r\n                                                        onShowWeeklyDefaultShift={this.props.onShowWeeklyDefaultShift}\r\n                                                        onUpdateRemark={this.props.onUpdateRemark}\r\n                                                        onChangeOrder={this.props.onChangeOrder}\r\n                                                        onSelectEmployeeOfTeam={this.props.onSelectEmployeeOfTeam}\r\n                                                    />\r\n                                                    {memberProvided.placeholder}\r\n                                                </div>\r\n                                        }\r\n                                    </Draggable>\r\n                                )\r\n                            }\r\n                            {provided.placeholder}\r\n                        </div>\r\n                }\r\n            </Droppable>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport moment from 'moment';\r\n\r\nimport { DateTimeFormat, OffDayShiftId } from '../../../shared/constants';\r\nimport ColIndex from './ColIndex';\r\nimport ColNickname from './ColNickname';\r\nimport ColDefaultShift from './ColDefaultShift';\r\nimport ColShift from './ColShift';\r\n\r\nexport default class Row extends PureComponent {\r\n    handleChangeSelectWeekDay = (attrName, isChecked) => {\r\n        const { teamId, data } = this.props;\r\n        const employeeId = data.employeeId;\r\n\r\n        this.props.onChangeSelectWeekDay(teamId, employeeId, attrName, isChecked);\r\n    };\r\n\r\n    handleChangeShift = (name, shift) => {\r\n        const { teamId, data } = this.props;\r\n        const employeeId = data.employeeId;\r\n\r\n        this.props.onChangeShift(teamId, employeeId, name, shift);\r\n    };\r\n\r\n    handleSelectEmployee = event => {\r\n        const { teamId, data } = this.props;\r\n        const employeeId = data.employeeId;\r\n        this.props.onSelectEmployeeOfTeam(teamId, employeeId, event.target.checked);\r\n    };\r\n\r\n    render() {\r\n        const { isHost, shiftOptions, teamId, data, showRemarkPopover, draggableProvided, isDragging } = this.props;\r\n        const enableSyncWorkingShift = document.getElementById('EnableSyncWorkingShift').checked;\r\n\r\n        return (\r\n            <div className={`table-row ${isDragging ? 'dragging' : ''}`}\r\n                ref={draggableProvided.innerRef} {...draggableProvided.draggableProps} {...draggableProvided.dragHandleProps}\r\n            >\r\n                <ColIndex data={data} />\r\n                <ColNickname isHost={isHost}\r\n                    teamId={teamId} employeeId={data.employeeId} nickname={data.nickname} remark={data.remark}\r\n                    showRemarkPopover={showRemarkPopover}\r\n                    onChangeShowRemarkPopover={this.props.onChangeShowRemarkPopover}\r\n                    onShowWeeklyDefaultShift={this.props.onShowWeeklyDefaultShift}\r\n                    onUpdateRemark={this.props.onUpdateRemark}\r\n                    onChangeOrder={this.props.onChangeOrder}\r\n                />\r\n                <ColDefaultShift isHost={isHost} teamId={teamId} employeeId={data.employeeId}\r\n                    isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift} data={data.defaultShift}\r\n                    shiftOptions={shiftOptions.filter(shift => shift.id !== OffDayShiftId)}\r\n                    onChangeDefaultShift={this.props.onChangeDefaultShift}\r\n                />\r\n                <ColShift isHost={isHost} shiftOptions={shiftOptions} isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.mondaySchedule}\r\n                    scheduleAttrName={'mondaySchedule'}\r\n                    isChecked={data.selectWeekDays.mondaySchedule}\r\n                    onChangeShift={this.handleChangeShift}\r\n                    onChangeSelectWeekDay={this.handleChangeSelectWeekDay}\r\n                />\r\n                <ColShift isHost={isHost} shiftOptions={shiftOptions} isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.tuesdaySchedule}\r\n                    scheduleAttrName={'tuesdaySchedule'}\r\n                    isChecked={data.selectWeekDays.tuesdaySchedule}\r\n                    onChangeShift={this.handleChangeShift}\r\n                    onChangeSelectWeekDay={this.handleChangeSelectWeekDay}\r\n                />\r\n                <ColShift isHost={isHost} shiftOptions={shiftOptions} isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.wednesdaySchedule}\r\n                    scheduleAttrName={'wednesdaySchedule'}\r\n                    isChecked={data.selectWeekDays.wednesdaySchedule}\r\n                    onChangeShift={this.handleChangeShift}\r\n                    onChangeSelectWeekDay={this.handleChangeSelectWeekDay}\r\n                />\r\n                <ColShift isHost={isHost} shiftOptions={shiftOptions} isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.thursdaySchedule}\r\n                    scheduleAttrName={'thursdaySchedule'}\r\n                    isChecked={data.selectWeekDays.thursdaySchedule}\r\n                    onChangeShift={this.handleChangeShift}\r\n                    onChangeSelectWeekDay={this.handleChangeSelectWeekDay}\r\n                />\r\n                <ColShift isHost={isHost} shiftOptions={shiftOptions} isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.fridaySchedule}\r\n                    scheduleAttrName={'fridaySchedule'}\r\n                    isChecked={data.selectWeekDays.fridaySchedule}\r\n                    onChangeShift={this.handleChangeShift}\r\n                    onChangeSelectWeekDay={this.handleChangeSelectWeekDay}\r\n                />\r\n                <ColShift isHost={isHost} shiftOptions={shiftOptions} isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.saturdaySchedule}\r\n                    scheduleAttrName={'saturdaySchedule'}\r\n                    isChecked={data.selectWeekDays.saturdaySchedule}\r\n                    onChangeShift={this.handleChangeShift}\r\n                    onChangeSelectWeekDay={this.handleChangeSelectWeekDay}\r\n                />\r\n                <ColShift isHost={isHost} shiftOptions={shiftOptions} isUsedWeeklyDefaultShift={data.isUsedWeeklyDefaultShift}\r\n                    employeeId={data.employeeId} defaultShift={data.defaultShift} data={data.sundaySchedule}\r\n                    scheduleAttrName={'sundaySchedule'}\r\n                    isChecked={data.selectWeekDays.sundaySchedule}\r\n                    onChangeShift={this.handleChangeShift}\r\n                    onChangeSelectWeekDay={this.handleChangeSelectWeekDay}\r\n                />\r\n                {\r\n                    isHost && enableSyncWorkingShift &&\r\n                    <div className=\"table-cell cell-syncdata\">\r\n                        <div className=\"checkbox\">\r\n                            <input type=\"checkbox\" className={`checkbox-custom`} id={`ckb-syncdata${data.employeeId}`}\r\n                                checked={data.isSelected} onChange={this.handleSelectEmployee}\r\n                            />\r\n                            <label htmlFor={`ckb-syncdata${data.employeeId}`} />\r\n                        </div>\r\n                    </div>\r\n                }\r\n                <div className=\"table-cell cell-modifier\">\r\n                    {\r\n                        data.modifier &&\r\n                        <span title={moment(data.modifiedDate).format(DateTimeFormat)}>\r\n                            {data.modifier}\r\n                        </span>\r\n                    }\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { OverlayTrigger, Tooltip } from 'react-bootstrap';\r\n\r\nimport DropdownOrder from '../../../shared/components/DropdownOrder';\r\n\r\nexport default class ColNickname extends PureComponent {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            remark: props.remark !== null ? props.remark : '',\r\n            showPopover: false\r\n        };\r\n    }\r\n\r\n    handleShowPopover = () => {\r\n        const { isHost, showRemarkPopover } = this.props;\r\n\r\n        if (isHost && !this.state.showPopover && !showRemarkPopover) {\r\n            this.setState({ showPopover: true });\r\n            this.props.onChangeShowRemarkPopover(true);\r\n        }\r\n    };\r\n\r\n    handleHidePopover = () => {\r\n        this.setState({ showPopover: false });\r\n        this.props.onChangeShowRemarkPopover(false);\r\n    };\r\n\r\n    handleShowWeeklyDefaultShiftModal = () => {\r\n        const { teamId, employeeId } = this.props;\r\n        this.props.onShowWeeklyDefaultShift(teamId, employeeId);\r\n    };\r\n\r\n    handleChangeRemark = event => {\r\n        this.setState({ remark: event.target.value });\r\n    };\r\n\r\n    handleUpdateRemark = () => {\r\n        const remark = this.state.remark.trim();\r\n        const { teamId, employeeId } = this.props;\r\n\r\n        this.handleHidePopover();\r\n        this.props.onChangeShowRemarkPopover(false);\r\n        this.props.onUpdateRemark(teamId, employeeId, remark);\r\n    };\r\n\r\n    handleMoveUp = () => {\r\n        const { teamId, employeeId } = this.props;\r\n        this.props.onChangeOrder('up', teamId, employeeId);\r\n    };\r\n\r\n    handleMoveDown = () => {\r\n        const { teamId, employeeId } = this.props;\r\n        this.props.onChangeOrder('down', teamId, employeeId);\r\n    };\r\n\r\n    handleMoveTop = () => {\r\n        const { teamId, employeeId } = this.props;\r\n        this.props.onChangeOrder('top', teamId, employeeId);\r\n    };\r\n\r\n    handleMoveBottom = () => {\r\n        const { teamId, employeeId } = this.props;\r\n        this.props.onChangeOrder('bottom', teamId, employeeId);\r\n    };\r\n\r\n    render() {\r\n        const { isHost, employeeId, nickname, remark } = this.props;\r\n\r\n        return (\r\n            <div className=\"table-cell cell-nickname\">\r\n                <div className=\"cell-nickname-wrapper\">\r\n                    <div className=\"info\">\r\n                        <div className=\"nickname\">{nickname}</div>\r\n                        <div className=\"remark-wrapper\">\r\n                            <i className={`icon-remark ${remark !== null && remark.length > 0 ? 'has-remark' : ''} fa fa-commenting-o`}\r\n                                title=\"Remark\"\r\n                                onClick={this.handleShowPopover}\r\n                            />\r\n                            <OverlayTrigger trigger={['hover']} placement={'top'}\r\n                                overlay={<Tooltip id={`remark${employeeId}`}>{remark}</Tooltip>}\r\n                            >\r\n                                <span className=\"remark\">{remark}</span>\r\n                            </OverlayTrigger>\r\n                            {\r\n                                this.state.showPopover &&\r\n                                <div className=\"remark-popover\">\r\n                                    <div className=\"input-field\">\r\n                                        <label>Remark</label>\r\n                                        <textarea maxLength=\"200\" autoFocus value={this.state.remark} onChange={this.handleChangeRemark} />\r\n                                    </div>\r\n                                    <div className=\"btn-control\">\r\n                                        <a className=\"btn btn-primary\" onClick={this.handleUpdateRemark}>Save</a>\r\n                                        <a className=\"btn btn-default\" onClick={this.handleHidePopover}>Cancel</a>\r\n                                    </div>\r\n                                </div>\r\n                            }\r\n                        </div>\r\n                    </div>\r\n                    <div className=\"action\">\r\n                        <i className=\"icon icon-default-shift\" title=\"Weekly default shift\"\r\n                            onClick={this.handleShowWeeklyDefaultShiftModal}\r\n                        />\r\n                        {\r\n                            isHost &&\r\n                            <DropdownOrder id={`dropdown${employeeId}`}\r\n                                onMoveUp={this.handleMoveUp}\r\n                                onMoveDown={this.handleMoveDown}\r\n                                onMoveTop={this.handleMoveTop}\r\n                                onMoveBottom={this.handleMoveBottom}\r\n                            />\r\n                        }\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport ShiftAutocomplete from '../ShiftAutocomplete';\r\n\r\nexport default class ColDefaultShift extends PureComponent {\r\n    handleChangeDefaultShift = (name, shift) => {\r\n        const { teamId, employeeId } = this.props;\r\n        this.props.onChangeDefaultShift(teamId, employeeId, shift);\r\n    };\r\n\r\n    render() {\r\n        const { isHost, shiftOptions, data, isUsedWeeklyDefaultShift } = this.props;\r\n\r\n        return (\r\n            <div className={`table-cell cell-shift cell-default-shift ${isUsedWeeklyDefaultShift ? 'is-weekly' : ''}`}>\r\n                {\r\n                    !isUsedWeeklyDefaultShift &&\r\n                    <ShiftAutocomplete isDisabled={!isHost}\r\n                        shift={data} shiftOptions={shiftOptions}\r\n                        onChange={this.handleChangeDefaultShift}\r\n                    />\r\n                }\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nimport { OffDayShiftId } from '../../../shared/constants';\r\nimport { getColumnShiftInfo } from '../common.functions';\r\nimport ShiftAutocomplete from '../ShiftAutocomplete';\r\nimport TooltipRequestInfo from './TooltipRequestInfo';\r\n\r\nexport default class ColShift extends PureComponent {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            isShowCheckbox: props.isChecked\r\n        };\r\n    }\r\n\r\n    componentDidUpdate(prevProps) {\r\n        if (this.props.isChecked !== prevProps.isChecked) {\r\n            this.setState({ isShowCheckbox: this.props.isChecked });\r\n        }\r\n    }\r\n\r\n    handleChangeSelectWeekDay = event => {\r\n        this.props.onChangeSelectWeekDay(this.props.scheduleAttrName, event.target.checked);\r\n    };\r\n\r\n    handleChangeShift = (scheduleAttrName, shift) => {\r\n        this.props.onChangeShift(scheduleAttrName, shift);\r\n    };\r\n\r\n    handleMouseOver = () => {\r\n        if (!this.state.isShowCheckbox) {\r\n            this.setState({ isShowCheckbox: true });\r\n        }\r\n    };\r\n\r\n    handleMouseLeave = () => {\r\n        if (this.state.isShowCheckbox && !this.props.isChecked) {\r\n            this.setState({ isShowCheckbox: false });\r\n        }\r\n    };\r\n\r\n    render() {\r\n        const { employeeId, data, isHost, scheduleAttrName, defaultShift, shiftOptions, isUsedWeeklyDefaultShift } = this.props;\r\n        const shiftInfo = getColumnShiftInfo(data, isHost, defaultShift, isUsedWeeklyDefaultShift);\r\n\r\n        let shift;\r\n        if (data.shift === null) {\r\n            shift = { code: shiftInfo.value, name: shiftInfo.value };\r\n        } else if (data.shift.code !== shiftInfo.value) {\r\n            shift = { ...data.shift, code: shiftInfo.value, name: shiftInfo.value };\r\n        } else {\r\n            shift = data.shift;\r\n        }\r\n\r\n        return (\r\n            <div className=\"table-cell cell-shift\" onMouseOver={this.handleMouseOver} onMouseLeave={this.handleMouseLeave}>\r\n                <div className={`cell-shift-wrapper ${data.isLeaveHalfDay ? 'leavehalfday' : ''}`}>\r\n                    {\r\n                        shiftInfo.details !== '' &&\r\n                        <TooltipRequestInfo id={`moreInfo-${scheduleAttrName}${employeeId}`}\r\n                            requestInfo={shiftInfo}\r\n                            isLeaveHalfDay={data.isLeaveHalfDay}\r\n                        />\r\n                    }\r\n                    <ShiftAutocomplete\r\n                        shift={shift}\r\n                        name={scheduleAttrName}\r\n                        className={shiftInfo.class}\r\n                        placeholder={shiftInfo.placeholder}\r\n                        isDisabled={shiftInfo.isDisabled}\r\n                        shiftOptions={data.isLeaveHalfDay || data.isChangeShift ? shiftOptions.filter(item => item.id !== OffDayShiftId) : shiftOptions}\r\n                        onChange={this.handleChangeShift}\r\n                    />\r\n                    <div className={`checkbox ${shiftInfo.isShowCheckBox && this.state.isShowCheckbox ? '' : 'hidden'}`}>\r\n                        <input type=\"checkbox\" className={`checkbox-custom ${scheduleAttrName}`} checked={this.props.isChecked}\r\n                            id={`ckb-${scheduleAttrName}${employeeId}`} onChange={this.handleChangeSelectWeekDay}\r\n                        />\r\n                        <label htmlFor={`ckb-${scheduleAttrName}${employeeId}`} />\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}"],"sourceRoot":""}
